-- 2026-11-07s UNDO: puts back the background timelines and checked dates of the 50 MPs changed by 2026-11-07s-background-new.sql
-- (member_ids 5229, 5230, 5231, 5233, 5234, 5235, 5236, 5237, 5238, 5239, 5240, 5242, 5243, 5244, 5245, 5246, 5247, 5248, 5249, 5250, 5251, 5252, 5253, 5254, 5255, 5256, 5258, 5259, 5260, 5261, 5262, 5263, 5264, 5265, 5266, 5267, 5268, 5269, 5270, 5271, 5272, 5273, 5274, 5275, 5276, 5277, 5278, 5279, 5280, 5281), exactly as they were when the migration was generated on 2026-11-07
-- (backup off the repo: "Claude outputs/backups/2026-11-07s-mp-biography-before.csv"). Each row changes only WHERE it still holds the
-- 2026-11-07s array (md5), so a later edit is never overwritten silently. No other row changes.
-- Guards (RAISE): exactly 50 rows change; nothing else changes; MPs with a timeline 596 to 546; 6,743 entries.
\set ON_ERROR_STOP on
BEGIN READ WRITE;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h FROM public.mp_biography b;

CREATE TEMP TABLE bt_restore (member_id integer PRIMARY KEY, tl jsonb, checked date, cur_md5 text NOT NULL) ON COMMIT DROP;

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_restore r USING (member_id) WHERE md5(b.background_timeline::text) = r.cur_md5) <> 50 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-11-07s value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = r.tl, background_last_checked = r.checked
  FROM bt_restore r WHERE b.member_id = r.member_id AND md5(b.background_timeline::text) = r.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  restored integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5229, 5230, 5231, 5233, 5234, 5235, 5236, 5237, 5238, 5239, 5240, 5242, 5243, 5244, 5245, 5246, 5247, 5248, 5249, 5250, 5251, 5252, 5253, 5254, 5255, 5256, 5258, 5259, 5260, 5261, 5262, 5263, 5264, 5265, 5266, 5267, 5268, 5269, 5270, 5271, 5272, 5273, 5274, 5275, 5276, 5277, 5278, 5279, 5280, 5281) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO restored FROM public.mp_biography b JOIN bt_restore r USING (member_id)
   WHERE b.background_timeline IS NOT DISTINCT FROM r.tl AND b.background_last_checked IS NOT DISTINCT FROM r.checked;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 50 %, rows restored exactly %, MPs with a timeline %, entries %', changed, changed_outside, restored, with_timeline, entry_total;
  IF changed <> 50 THEN RAISE EXCEPTION 'expected exactly 50 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 50 changed', changed_outside; END IF;
  IF restored <> 50 THEN RAISE EXCEPTION 'expected 50 rows restored exactly, got %', restored; END IF;
  IF with_timeline <> 546 THEN RAISE EXCEPTION 'expected 546 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 6743 THEN RAISE EXCEPTION 'expected 6743 entries, got %', entry_total; END IF;
END $$;

COMMIT;
